mapper.update:
UPDATE USER
SET USER_PHONE = #{receiverPhone}
WHERE USER_ID = #{userId}
AND (USER_PHONE IS NULL OR USER_PHONE = '')

UPDATE USER_ADDRESS
SET
ADDRESS_ALIAS = #{addressAlias},
ZIPCODE = #{zipCode},
ADDRESS = #{address},
DETAILED_ADDRESS = #{detailedAddress},
DEFAULT_YN = #{defaultYn}
WHERE ADDRESS_ID = #{addressId}
AND USER_ID = #{userId}

mapper.delete:
DELETE FROM USER_ADDRESS
WHERE ADDRESS_ID = #{addressId}
AND USER_ID = #{userId}
